<input id="distanceSliderInput" type="range" min="20" max="400" step="1" value="74"
 oninput="document.getElementById('distanceSliderVal').value=this.value;update_distanceSlider(+this.value)"></label>
<p style="margin:0;font-size:10px;color:#555">Click the repulsive wall, the well, or the far tail of the curve to learn why each region behaves as it does.</p>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Morse-like potential for H₂ ──────────────────────────────────────────
// E(r): steep wall at small r, minimum at r = 74 pm, E → 0 as r → ∞
function energyOf(r) {
  var x = r / 74;
  return 4.6 * (Math.exp(-2.1 * (x - 1)) - 2 * Math.exp(-1.05 * (x - 1)));
}

var rMin = 20, rMax = 400;
var curveData = [];
for (var r = rMin; r <= rMax; r += 2) curveData.push({ x: r, y: energyOf(r) });

var currentR = 74;
var highlightRegion = null; // 'close' | 'well' | 'far'

// ── Custom plugin: vignettes, axes symbols, marker, bond-length arrow ────
var vignettePlugin = {
  id: 'vignettes',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx;
    var a = chart.chartArea;
    var meta = chart.getDatasetMeta(0);
    var x0 = chart.scales.x.getPixelForValue(0);
    var yZero = chart.scales.y.getPixelForValue(0);
    var yWell = chart.scales.y.getPixelForValue(energyOf(74));
    var xWell = chart.scales.x.getPixelForValue(74);
    var scale = Math.min(a.right - a.left, a.bottom - a.top) / 400;
    var R = Math.max(6, 14 * scale + 6); // sphere radius
    var fs = Math.max(10, 13 * scale + 4);

    function halo(txt) {
      ctx.save();
      ctx.font = 'bold ' + fs + 'px sans-serif';
      ctx.textAlign = 'center';
      ctx.strokeStyle = 'rgba(255,255,255,0.9)';
      ctx.lineWidth = 3;
      ctx.lineJoin = 'round';
      ctx.strokeText.apply(ctx, txt);
      ctx.fillStyle = '#1a7a3c';
      ctx.fillText.apply(ctx, txt);
      ctx.restore();
    }
    function sphere(cx, cy, r) {
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, Math.PI * 2);
      ctx.fillStyle = '#2e9e4f';
      ctx.fill();
      ctx.strokeStyle = '#14692e';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(cx - r * 0.35, cy - r * 0.35, r * 0.3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.45)';
      ctx.fill();
    }
    function glow(cx, cy, w, h) {
      ctx.save();
      ctx.shadowColor = 'rgba(255,180,0,0.9)';
      ctx.shadowBlur = 22;
      ctx.strokeStyle = 'rgba(230,150,0,0.8)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.ellipse(cx, cy, w, h, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }

    // ── Vignette 1: HH (too close), overlapping spheres top-left ──
    var x1 = chart.scales.x.getPixelForValue(38);
    var y1 = chart.scales.y.getPixelForValue(energyOf(38)) - R * 1.6;
    y1 = Math.max(y1, a.top + R + 2);
    if (highlightRegion === 'close') glow(x1, y1, R * 2.2, R * 1.6);
    sphere(x1 - R * 0.7, y1, R);
    sphere(x1 + R * 0.7, y1, R);
    halo(['HH (too close)', x1, y1 - R * 1.5]);

    // ── Vignette 2: H—H touching spheres at the well ──
    var x2 = xWell - R * 1.4;
    var y2 = yWell - R * 1.9;
    if (highlightRegion === 'well') glow(x2, y2, R * 2.4, R * 1.6);
    sphere(x2 - R, y2, R);
    sphere(x2 + R, y2, R);
    halo(['H—H', x2, y2 + R * 2.1]);

    // ── Vignette 3: H - - - H (too far) ──
    var x3a = chart.scales.x.getPixelForValue(230);
    var x3b = chart.scales.x.getPixelForValue(315);
    var y3 = chart.scales.y.getPixelForValue(0.9);
    if (highlightRegion === 'far') glow((x3a + x3b) / 2, y3, (x3b - x3a) / 2 + R, R * 1.6);
    sphere(x3a, y3, R);
    sphere(x3b, y3, R);
    ctx.save();
    ctx.strokeStyle = '#d63384';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(x3a + R, y3);
    ctx.lineTo(x3b - R, y3);
    ctx.stroke();
    ctx.restore();
    ctx.save();
    ctx.font = 'bold ' + fs + 'px sans-serif';
    ctx.textAlign = 'center';
    ctx.strokeStyle = 'rgba(255,255,255,0.9)';
    ctx.lineWidth = 3;
    ctx.strokeText('H - - - H (too far)', (x3a + x3b) / 2, y3 - R * 1.5);
    ctx.fillStyle = '#d63384';
    ctx.fillText('H - - - H (too far)', (x3a + x3b) / 2, y3 - R * 1.5);
    ctx.restore();

    // ── Vertical dashed line at minimum + '74 pm' label ──
    ctx.save();
    ctx.strokeStyle = '#1a7a3c';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(xWell, yWell);
    ctx.lineTo(xWell, yWell + 26 * scale + 14);
    ctx.stroke();
    ctx.restore();
    ctx.save();
    ctx.font = 'bold ' + fs + 'px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#1a7a3c';
    ctx.strokeStyle = 'rgba(255,255,255,0.9)';
    ctx.lineWidth = 3;
    ctx.strokeText('74 pm', xWell, yWell + 30 * scale + 26);
    ctx.fillText('74 pm', xWell, yWell + 30 * scale + 26);
    ctx.restore();

    // ── Green 'Bond length' arrow → minimum ──
    var ax0 = xWell + (a.right - a.left) * 0.18;
    var ay0 = yWell + 30 * scale + 22;
    ctx.save();
    ctx.strokeStyle = '#1a7a3c';
    ctx.fillStyle = '#1a7a3c';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(ax0, ay0);
    ctx.lineTo(xWell + 6, yWell + 8);
    ctx.stroke();
    // arrowhead
    var ang = Math.atan2(yWell + 8 - ay0, xWell + 6 - ax0);
    ctx.beginPath();
    ctx.moveTo(xWell + 6, yWell + 8);
    ctx.lineTo(xWell + 6 - 9 * Math.cos(ang - 0.4), yWell + 8 - 9 * Math.sin(ang - 0.4));
    ctx.lineTo(xWell + 6 - 9 * Math.cos(ang + 0.4), yWell + 8 - 9 * Math.sin(ang + 0.4));
    ctx.closePath();
    ctx.fill();
    ctx.font = 'bold ' + fs + 'px sans-serif';
    ctx.textAlign = 'left';
    ctx.strokeStyle = 'rgba(255,255,255,0.9)';
    ctx.lineWidth = 3;
    ctx.strokeText('Bond length', ax0 + 6, ay0 + 4);
    ctx.fillText('Bond length', ax0 + 6, ay0 + 4);
    ctx.restore();

    // ── + / 0 / − symbols on the energy "axis" ──
    ctx.save();
    ctx.font = 'bold ' + (fs + 4) + 'px sans-serif';
    ctx.textAlign = 'right';
    ctx.fillStyle = '#333';
    ctx.fillText('+', a.left - 8, a.top + (yZero - a.top) * 0.45);
    ctx.fillText('0', a.left - 8, yZero + 5);
    ctx.fillText('−', a.left - 8, yZero + (a.bottom - yZero) * 0.55);
    ctx.restore();

    // ── Movable marker on the curve + current atom pair ──
    var px = chart.scales.x.getPixelForValue(currentR);
    var py = chart.scales.y.getPixelForValue(energyOf(currentR));
    ctx.save();
    ctx.beginPath();
    ctx.arc(px, py, 7, 0, Math.PI * 2);
    ctx.fillStyle = '#fff';
    ctx.fill();
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#d63384';
    ctx.stroke();
    ctx.restore();

    // current atom pair: separation ∝ slider, placed just above marker
    var sep = Math.max(R * 0.6, R * 2 * Math.pow(currentR / 74, 0.55));
    var my = py - R * 2.6;
    if (my - R < a.top + 2) my = a.top + R + 2;
    sphere(px - sep / 2, my, R * 0.85);
    sphere(px + sep / 2, my, R * 0.85);
    ctx.save();
    ctx.font = 'bold ' + (fs - 1) + 'px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#1a7a3c';
    ctx.strokeStyle = 'rgba(255,255,255,0.9)';
    ctx.lineWidth = 3;
    ctx.strokeText(currentR + ' pm', px, my + R * 2.2);
    ctx.fillText(currentR + ' pm', px, my + R * 2.2);
    ctx.restore();

    // ── Energy arrow at far left (outside plot area) ──
    var gx = Math.max(16, a.left * 0.42);
    var grd = ctx.createLinearGradient(0, a.bottom, 0, a.top);
    grd.addColorStop(0, '#fdf3d0');
    grd.addColorStop(1, '#f2701d');
    var aw = Math.max(10, 20 * scale + 6);
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(gx, a.top - 14);               // tip
    ctx.lineTo(gx + aw / 2, a.top + 2);
    ctx.lineTo(gx + aw / 5, a.top + 2);
    ctx.lineTo(gx + aw / 5, a.bottom);
    ctx.lineTo(gx - aw / 5, a.bottom);
    ctx.lineTo(gx - aw / 5, a.top + 2);
    ctx.lineTo(gx - aw / 2, a.top + 2);
    ctx.closePath();
    ctx.fillStyle = grd;
    ctx.fill();
    ctx.strokeStyle = '#555';
    ctx.lineWidth = 1;
    ctx.stroke();
    // rotated 'Energy' label
    ctx.translate(gx, (a.top + a.bottom) / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.font = 'bold ' + fs + 'px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#333';
    ctx.fillText('Energy', 0, 4);
    ctx.restore();

    // ── Axis captions ──
    ctx.save();
    ctx.font = 'bold ' + fs + 'px sans-serif';
    ctx.fillStyle = '#333';
    ctx.textAlign = 'center';
    ctx.fillText('Internuclear distance', (a.left + a.right) / 2, a.bottom + 34);
    // magenta arrowhead
    var ax = (a.left + a.right) / 2 + ctx.measureText('Internuclear distance').width / 2 + 12;
    ctx.strokeStyle = '#d63384';
    ctx.fillStyle = '#d63384';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(ax, a.bottom + 30);
    ctx.lineTo(ax + 22, a.bottom + 30);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(ax + 28, a.bottom + 30);
    ctx.lineTo(ax + 18, a.bottom + 26);
    ctx.lineTo(ax + 18, a.bottom + 34);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
};

// ── Chart ────────────────────────────────────────────────────────────────
var canvas = document.createElement('canvas');
canvas.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(canvas);

var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [{
      data: curveData,
      borderColor: '#d63384',
      borderWidth: 3,
      pointRadius: 0,
      tension: 0.25
    }]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    layout: { padding: { left: 34, top: 20, bottom: 44, right: 16 } },
    events: ['click'],
    onClick: function (e) {
      var rect = canvas.getBoundingClientRect();
      var x = e.clientX - rect.left;
      var r = chart.scales.x.getValueForPixel(x);
      if (r < 62) {
        highlightRegion = 'close';
        showPopup('Too close: the repulsive wall',
          'Below about 60 pm the two positively charged nuclei repel strongly and the energy shoots almost vertically upward. This is why a bond cannot be shorter than its equilibrium length.');
      } else if (r < 130) {
        highlightRegion = 'well';
        showPopup('The energy well: the bond',
          'At 74 pm attraction between each electron and the opposite nucleus exactly balances nuclear repulsion, giving the lowest energy. This separation is the covalent bond length of H₂.');
      } else {
        highlightRegion = 'far';
        showPopup('Too far: the atoms no longer interact',
          'Beyond a few hundred pm the atoms barely influence each other, so the energy climbs back toward zero — the energy of two isolated hydrogen atoms. No bond survives here.');
      }
      chart.update();
    },
    onHover: function (e) {
      canvas.style.cursor = 'pointer';
      var rect = canvas.getBoundingClientRect();
      var x = e.clientX - rect.left;
